+import { writeFileSync } from "node:fs";
+import { runQuery } from "./query";
+import { toCsv } from "./csv";
+import { renderPdf } from "./pdf";
+
+export interface ReportOptions {
+  format: "pdf" | "csv";
+  out: string;
+  since?: string;
+}
+
+export async function reportsCommand(opts: ReportOptions): Promise<void> {
+  const rows = await runQuery({ since: opts.since });
+  if (opts.format === "csv") {
+    writeFileSync(opts.out, toCsv(rows));
+    return;
+  }
+  await renderPdf(rows, opts.out);
+}"}, {"sha": "0000000000000000000000000000000000000000", "filename": "src/reports/csv.ts", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/acme/tidewater/blob/feature/src/reports/csv.ts", "raw_url": "https://github.com/acme/tidewater/raw/feature/src/reports/csv.ts", "contents_url": "https://api.github.com/repos/acme/tidewater/contents/src/reports/csv.ts?ref=feature", "patch": "@@ -0,0 +1,17 @@
+import type { ReportRow } from "./query";
+
+const HEADER = ["date", "account", "description", "amount"];
+
+function cell(value: string | number): string {
+  const text = String(value);
+  if (/[",\n]/.test(text)) return `"${text.replace(/"/g, "'")}"`;
+  return text;
+}
+
+export function toCsv(rows: ReportRow[]): string {
+  const lines = [HEADER.join(",")];
+  for (const row of rows) {
+    lines.push([row.date, row.account, row.description, row.amount].map(cell).join(","));
+  }
+  return lines.join("\n");
+}"}, {"sha": "0000000000000000000000000000000000000000", "filename": "src/reports/query.ts", "status": "modified", "additions": 7, "deletions": 2, "changes": 9, "blob_url": "https://github.com/acme/tidewater/blob/feature/src/reports/query.ts", "raw_url": "https://github.com/acme/tidewater/raw/feature/src/reports/query.ts", "contents_url": "https://api.github.com/repos/acme/tidewater/contents/src/reports/query.ts?ref=feature", "patch": "@@ -10,6 +10,10 @@ export interface ReportRow {
